// Generated by Cypress Author on 2026-10-08.
import type { ListeningActivityItem, RecentlyPlayedResponse } from '../../../../backend/src/types/api';
import RecentListeningActivity from '../../../src/components/RecentListeningActivity';

const track: ListeningActivityItem = { trackId: 'repeat', name: 'Repeated song', artists: ['Artist'], albumCoverUrl: null, durationMs: 180000, playedAt: '2026-10-08T12:00:00' };

describe('RecentListeningActivity', () => {
  it('shuffled listens across local days → sorts descending and preserves repeated songs', () => {
    const items = [
      { ...track, playedAt: '2026-10-07T23:59:00' },
      { ...track, name: 'Latest song', playedAt: '2026-10-08T16:00:00' },
      track,
      { ...track, playedAt: '2026-10-06T18:00:00' },
    ];
    cy.intercept('GET', '/api/recently-played', { body: { items } satisfies RecentlyPlayedResponse }).as('activity');
    cy.mount(<RecentListeningActivity />);
    cy.wait('@activity');
    cy.get('[data-cy="track-name"]').should('have.length', 4).then(($names) => {
      expect([...$names].map((name) => name.textContent)).to.deep.equal(['Latest song', 'Repeated song', 'Repeated song', 'Repeated song']);
    });
    cy.get('h3').should('have.length', 3).then(($headings) => {
      const dates = ['2026-10-08T12:00:00', '2026-10-07T12:00:00', '2026-10-06T12:00:00'];
      expect([...$headings].map((heading) => heading.textContent)).to.deep.equal(dates.map((date) => new Date(date).toLocaleDateString(undefined, { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })));
    });
    cy.get('ol').first().find('li').should('have.length', 2);
    cy.get('time').then(($times) => expect([...$times].map((time) => time.getAttribute('datetime'))).to.deep.equal([items[1].playedAt, track.playedAt, items[0].playedAt, items[3].playedAt]));
  });

  it('no recent songs → shows the empty listening diary', () => {
    cy.intercept('GET', '/api/recently-played', { body: { items: [] } satisfies RecentlyPlayedResponse }).as('activity');
    cy.mount(<RecentListeningActivity />);
    cy.wait('@activity');
    cy.contains('No recent listening activity yet.').should('be.visible');
    cy.get('[data-cy="listening-track"]').should('not.exist');
  });

  it('request fails → shows an accessible error', () => {
    cy.intercept('GET', '/api/recently-played', { statusCode: 502, body: { error: 'Spotify unavailable' } }).as('activity');
    cy.mount(<RecentListeningActivity />);
    cy.wait('@activity');
    cy.get('[role="alert"]').should('contain.text', 'Could not load your recent listening activity');
    cy.get('[role="status"]').should('not.exist');
  });

  it('request pending → shows loading until the response arrives', () => {
    let release: (() => void) | undefined;
    cy.intercept('GET', '/api/recently-played', (request) => new Cypress.Promise<void>((resolve) => {
      release = () => { request.reply({ body: { items: [] } }); resolve(); };
    })).as('activity');
    cy.mount(<RecentListeningActivity />);
    cy.get('[role="status"]').should('contain.text', 'Loading your recent listening activity');
    cy.wrap(null).should(() => expect(release).to.be.a('function')).then(() => release?.());
    cy.wait('@activity');
    cy.contains('No recent listening activity yet.').should('be.visible');
  });
});
